1139	                contactForm.addEventListener('submit', function(e) {
1140	                    e.preventDefault();
1141	
1142	                    if (isSubmitting) return;
1143	
1144	                    let isValid = true;
1145	                    const feedback = document.getElementById('form-feedback');
1146	                    feedback.className = 'form-feedback';
1147	                    feedback.textContent = '';
