1149	                    inputs.forEach(input => {
1150	                        if (!validateField(input)) isValid = false;
1151	                    });
1152	
1153	                    if (!isValid) {
1154	                        feedback.className = 'form-feedback error';
1155	                        feedback.textContent = 'Please correct the errors above and try again.';
1156	                        feedback.setAttribute('role', 'alert');
1157	                        setTimeout(() => {
1158	                            feedback.focus();
1159	                            const firstError = contactForm.querySelector('[aria-invalid="true"]');
1160	                            if (firstError && firstError.focus) {
1161	                                firstError.focus();
1162	                            }
1163	                        }, 100);
1164	                        return;
1165	                    }
1166	
1167	                    const submitBtn = document.getElementById('submit-btn');
1168	                    isSubmitting = true;
1169	                    submitBtn.disabled = true;
1170	                    submitBtn.classList.add('loading');
1171	                    const originalHTML = submitBtn.innerHTML;
1172	                    const originalAriaLabel = submitBtn.getAttribute('aria-label');
