1178	                    const controller = new AbortController();
1179	                    const timeoutId = setTimeout(() => controller.abort(), 10000);
1180	
1181	                    fetch(endpoint, {
1182	                        method: 'POST',
1183	                        body: formData,
1184	                        signal: controller.signal
1185	                    })
1186	                    .then(response => {
1187	                        if (!response.ok) {
1188	                            throw new Error(`Server error: ${response.status}`);
1189	                        }
1190	                        return response;
1191	                    })
