1202	                    })
1203	                    .catch(error => {
1204	                        feedback.className = 'form-feedback error';
1205	                        if (error.name === 'AbortError') {
1206	                            feedback.textContent = 'Request timed out. Please try again.';
1207	                        } else if (error instanceof TypeError) {
